"""Interface definitions to reduce coupling between components."""

from typing import List, Optional, Protocol, Union

from .models import Coin, Pair, ScoutHistory, Trade


class DatabaseInterface(Protocol):
    """Interface for database operations to decouple concrete implementations."""

    def db_session(self):
        """Context manager yielding an open SQLAlchemy session."""
        ...

    def set_coins(self, symbols: List[str]) -> None:
        """Set supported coins in the database."""
        ...

    def get_coins(self, only_enabled: bool = True) -> List[Coin]:
        """Get list of coins."""
        ...

    def get_coin(self, coin: Union[Coin, str]) -> Coin:
        """Get a specific coin by symbol or Coin object."""
        ...

    def set_current_coin(self, coin: Union[Coin, str]) -> None:
        """Set the current coin being traded."""
        ...

    def get_current_coin(self) -> Optional[Coin]:
        """Get the current coin being traded."""
        ...

    def get_pairs_from(self, from_coin: Union[Coin, str], only_enabled: bool = True) -> List[Pair]:
        """Get all pairs starting from a given coin."""
        ...

    def log_scout(
        self,
        pair: Pair,
        target_ratio: float,
        current_coin_price: float,
        other_coin_price: float,
    ) -> None:
        """Log a scouting decision."""
        ...


class ConfigInterface(Protocol):
    """Interface for configuration to decouple concrete Config class."""

    @property
    def BRIDGE(self) -> Coin:
        """Get the bridge coin."""
        ...

    @property
    def BRIDGE_SYMBOL(self) -> str:
        """Get the bridge symbol string."""
        ...

    @property
    def SUPPORTED_COIN_LIST(self) -> List[str]:
        """Get list of supported coin symbols."""
        ...

    @property
    def STRATEGY(self) -> str:
        """Get the strategy name."""
        ...

    @property
    def SCOUT_MARGIN(self) -> float:
        """Get scout margin percentage."""
        ...

    @property
    def SCOUT_MULTIPLIER(self) -> float:
        """Get scout multiplier."""
        ...

    @property
    def USE_MARGIN(self) -> str:
        """Get use margin configuration."""
        ...

    @property
    def SCOUT_SLEEP_TIME(self) -> int:
        """Get scout sleep time in seconds."""
        ...

    @property
    def Binance_API_KEY(self) -> str:
        """Get Binance API key."""
        ...

    @property
    def Binance_API_SECRET_KEY(self) -> str:
        """Get Binance API secret key."""
        ...

    @property
    def Binance_TLD(self) -> str:
        """Get Binance TLD (e.g., 'com', 'us')."""
        ...

    @property
    def TESTNET(self) -> bool:
        """Get testnet mode flag."""
        ...
